112	void SARBackproject::unwrap(double* angles) {
113	    // Store the first original angle for difference calculations.
114	    double prev_orig = angles[0];
115	    // The first angle remains unchanged.
116	    for (int i = 1; i < PULSES; i++) {
117	        // Save the current original value before modifying it.
118	        double current_orig = angles[i];
119	        double diff = current_orig - prev_orig;
120	        // Wrap diff into the range [-pi, pi)
121	        double dp = fmod(diff + PI, TWO_PI);
122	        if (dp < 0)
123	            dp += TWO_PI;
124	        dp -= PI;
125	        // Adjust the edge case: if dp == -pi and diff > 0, set dp to pi.
126	        if (dp == -PI && diff > 0)
127	            dp = PI;
128	        // The new (unwrapped) angle is the previous unwrapped angle plus dp.
129	        angles[i] = angles[i - 1] + dp;
130	        // Update prev_orig to the original value before modification.
131	        prev_orig = current_orig;
132	    }
