44	    aperture (\texttt{FileNum = 5}, \texttt{data.Nfft = 512}).}
45	    \label{fig:matlab_img_5}
46	  \end{subfigure}
47	  \caption{Generated MATLAB images from the GOTCHA dataset at two aperture
48	  extents.}
49	  \label{fig:matlab_img_side_by_side}
50	\end{figure}
51	
52	
53	\begin{lstlisting}[
54	  style=Matlab-editor,
55	  caption={MATLAB script for preprocessing input data and generating reference
56	  output imagery for Versal comparison. The function definition of
57	  \texttt{bpBasic(...)} is provided from the MATLAB code within "SAR Image
58	  Formation Toolbox for MATLAB" paper by Gorham et al. The
59	  \texttt{dlmwrite(...)} functions provide the preprocessed CSV input for
60	  Versal. \cite{Gorham}},
61	  label={lst:matlab_code},
62	  basicstyle=\ttfamily\footnotesize,
