64	]
65	% Author: Austin Owens
66	% Email: austin.t.owens@jpl.nasa.gov
67	%
68	% data.Nfft: Size of the FFT to form the range profile
69	% data.deltaF: Step size of frequency data (Hz)
70	% data.minF: Vector containing the start frequency of each pulse (Hz)
71	% data.x_mat: The x-position of each pixel (m)
72	% data.y_mat: The y-position of each pixel (m)
73	% data.z_mat: The z-position of each pixel (m)
74	% data.AntX: The x-position of the sensor at each pulse (m)
75	% data.AntY: The y-position of the sensor at each pulse (m)
76	% data.AntZ: The z-position of the sensor at each pulse (m)
77	% data.R0: The range to scene center (m)
78	% data.phdata: Phase history data (frequency domain)
79	%              Fast time in rows, slow time in columns
80	%
81	% data definitions:
82	% i.) data.fp: Phase history data (complex)
83	% ii.) data.freq: Column vector containing frequencies (Hz)
84	% iii.) data.x: Row vector containing the x-coordinate of the antenna location
85	% iv.) data.y: Row vector containing the y-coordinate of the antenna location
86	% v.) data.z: Row vector containing the z-coordinate of the antenna location
87	% vi.) data.r0: Row vector containing range to scene center from the antenna location
88	% vii.) data.th: Row vector containing azimuth angle. 0 degrees is the pos x-axis
89	% viii.) data.phi: Row vector containing elevation angle. 0 degrees is the xy-plane
90	% ix.) data.af: Structure containing autofocus information (only for HH and VV data). 
91	%      It contains 2 row vectors:
92	% x.) data.af.r_correct: Row vector containing the correction for r0
93	% xi.) data.af.ph_correct: Row vector containing the phase correction
94	
95	clc;clear;
96	
97	data.AntX = [];
98	data.AntY = [];
99	data.AntZ = [];
100	data.R0 = [];
101	data.phdata = [];
102	avg_delta_freq = 0;
103	min_freq = 0;
104	polarization = "HH";
105	
106	% Number of files to process. Each file represents 1 degree (360 deg total)
107	FileNum = 360;
108	
109	for n = 1:FileNum   
110	    str = sprintf('/mnt/disk/austin/SAR_DATA/GOTCHA-CP_Disc1/DATA/pass1/%s/data_3dsar_pass1_az%03d_%s.mat', polarization, n, polarization);
111	    az = load(str);
112	    data.AntX = [data.AntX, az.data.x];
113	    data.AntY = [data.AntY, az.data.y];
114	    data.AntZ = [data.AntZ, az.data.z];
115	    data.R0 = [data.R0, az.data.r0];
116	    data.phdata = [data.phdata, az.data.fp];
117	    avg_delta_freq = avg_delta_freq + mean(diff(az.data.freq));
118	    min_freq = az.data.freq(1);
119	end
120	data.deltaF = avg_delta_freq/FileNum;
121	
122	data.Nfft = 424;
123	data.minF = ones(size(data.AntX))*min_freq;
124	c = 299792458;
